def two_sum(nums, target):
    """Finds indices of two numbers that sum to target in O(N) time without nested loops."""
    if not nums: return []
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i
    return []

def top_k_words(words, k):
    """Returns top k most frequent words in list without collections or heapq."""
    if not words or k <= 0: return []
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    sorted_words = sorted(counts.keys(), key=lambda w: (-counts[w], words.index(w)))
    return sorted_words[:k]

def check_brackets(code):
    """Validates balanced delimiters using an invariant stack without regex."""
    if not code: return True
    mapping = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in code:
        if ch in '([{':
            stack.append(ch)
        elif ch in mapping:
            if not stack or stack[-1] != mapping[ch]:
                return False
            stack.pop()
    return len(stack) == 0
